'use strict';

// ════════════════════════════════════════════════════════════════════════════
// services/billingPayment.service.js
//
// Tenant self-pay for platform subscription invoices — a per-invoice Razorpay
// Order (NOT the Razorpay Subscriptions API: invoices are still generated by
// our own billing.service.js cron, this only adds an online way to settle
// one). Uses the PLATFORM's own Razorpay account (RAZORPAY_KEY_ID/SECRET),
// distinct from each tenant's own storefront keys on Tenant.razorpay.
//
// Verification never trusts the client-reported result — the signature is
// checked server-side and the payment status is re-fetched from Razorpay
// before anything is recorded, then applied through the same
// billingService.recordManualPayment() used for admin-recorded payments so
// invoice-status transitions, audit logging, receipts, and auto-reactivation
// all stay in one place.
// ════════════════════════════════════════════════════════════════════════════

const Razorpay = require('razorpay');
const crypto = require('crypto');
const billingService = require('./billing.service');
const logger = require('../utils/logger');

const httpError = (message, status = 400) => Object.assign(new Error(message), { status });
const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;

const getPlatformRazorpay = () => {
  const keyId = process.env.RAZORPAY_KEY_ID;
  const keySecret = process.env.RAZORPAY_KEY_SECRET;
  if (!keyId || !keySecret) {
    throw httpError('Online payment is not configured on this platform yet.', 503);
  }
  return { razorpay: new Razorpay({ key_id: keyId, key_secret: keySecret }), keyId, keySecret };
};

const createInvoicePaymentOrder = async (tenantId, invoiceId) => {
  const { razorpay, keyId } = getPlatformRazorpay();

  const sub = await billingService.getOrCreateSubscription(tenantId);
  const invoice = sub.invoices.id(invoiceId);
  if (!invoice) throw httpError('Invoice not found.', 404);
  if (['paid', 'cancelled', 'refunded'].includes(invoice.status)) {
    throw httpError(`This invoice is already ${invoice.status} — there's nothing to pay.`, 422);
  }

  const outstanding = round2(invoice.totalAmount - (invoice.paidAmount || 0));
  if (!(outstanding > 0)) throw httpError('There is nothing outstanding on this invoice.', 422);

  const order = await razorpay.orders.create({
    amount: Math.round(outstanding * 100),
    currency: 'INR',
    receipt: invoice.invoiceNumber.slice(0, 40),
    notes: { tenantId, invoiceId: String(invoice._id), invoiceNumber: invoice.invoiceNumber },
  });

  return {
    razorpayOrderId: order.id,
    amount: order.amount,
    currency: order.currency,
    keyId,
    invoiceNumber: invoice.invoiceNumber,
    outstanding,
  };
};

const verifyInvoicePayment = async (tenantId, invoiceId, payload, actingUser) => {
  const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = payload;
  if (!razorpay_order_id || !razorpay_payment_id || !razorpay_signature) {
    throw httpError('Missing payment verification fields.', 422);
  }

  // Idempotent re-submit guard (browser back/refresh after a successful pay).
  const subBefore = await billingService.getOrCreateSubscription(tenantId);
  const invoiceBefore = subBefore.invoices.id(invoiceId);
  if (!invoiceBefore) throw httpError('Invoice not found.', 404);
  if (invoiceBefore.status === 'paid') {
    return { subscription: subBefore, invoice: invoiceBefore, alreadyPaid: true };
  }

  const { razorpay, keySecret } = getPlatformRazorpay();

  const expected = crypto.createHmac('sha256', keySecret)
    .update(`${razorpay_order_id}|${razorpay_payment_id}`)
    .digest('hex');
  if (expected !== razorpay_signature) throw httpError('Invalid payment signature.', 400);

  // Never trust the client-reported status — re-fetch from Razorpay directly.
  const rzpPayment = await razorpay.payments.fetch(razorpay_payment_id);
  if (rzpPayment.order_id !== razorpay_order_id) {
    throw httpError('Payment does not match the order for this invoice.', 400);
  }
  if (rzpPayment.status !== 'captured' && rzpPayment.status !== 'authorized') {
    throw httpError(`Payment not confirmed by Razorpay (status: ${rzpPayment.status}).`, 400);
  }

  const amount = round2(rzpPayment.amount / 100);
  const result = await billingService.recordManualPayment(tenantId, invoiceId, {
    amount,
    method: 'Razorpay',
    referenceNumber: razorpay_payment_id,
    notes: 'Paid online via Razorpay',
    paidAt: new Date().toISOString(),
  }, actingUser);

  logger.info(`[BillingPayment] Online payment ${razorpay_payment_id} verified for ${tenantId} (₹${amount})`);
  return { ...result, alreadyPaid: false };
};

module.exports = { createInvoicePaymentOrder, verifyInvoicePayment };
